let serial=0;
export function convertCatalogItem(src,perfect=false){const slot=src.kind==='arma'?(src.position==='secundária'?'secondary':'weapon'):({'CB':'head','PT':'armor','MA':'hands','PE':'legs','BT':'boots','AN1':'ring1','AN2':'ring2','CO':'neck'}[src.slot]);const base={atk:Math.round((src.stats.af||0)+(src.stats.am||0)),hp:src.stats.hp||0,def:Math.round(((src.stats.df||0)+(src.stats.dm||0))/2),af:src.stats.af||0,am:src.stats.am||0,mp:src.stats.mp||src.stats.mana||0,acc:src.stats.precisao||0};const pct=['crit','critd','haste','ampF','ampM','cdr','critres','ten','pvp','maxcrit','critdres','ampres','ignoreCritRes','ignoreCritdRes','ignoreAmpRes'];const options=(perfect?Object.entries(src.native_caps):shuffle(Object.entries(src.native_caps))).slice(0,src.native_options_max).map(([type,cap])=>({type,value:(perfect?cap:rollCap(cap))/(pct.includes(type)?100:1)}));return {id:'lab-'+src.id+'-'+Date.now().toString(36)+'-'+(++serial),sourceId:src.id,weaponBudgetVersion:2,name:src.name,classId:src.class_id,level:src.level_min,slot,quality:src.rarity,base,options,enchant:0,slots:src.natural_slots_max,runes:[]};}
function rollCap(cap){const q=Math.random();return cap*(q<.55?.6+Math.random()*.15:q<.85?.751+Math.random()*.149:q<.98?.901+Math.random()*.098:1);}

function shuffle(values){for(let n=values.length-1;n>0;n--){const j=Math.floor(Math.random()*(n+1));[values[n],values[j]]=[values[j],values[n]];}return values;}
